-- Short mechanical reference for each moon, condensed from the book in the
-- GM's own words (not a verbatim transcription — the full rules text with
-- exact dice/DCs stays in the physical/PDF book, these are table-side
-- reminders of what each moon actually does, pointing back to book_page
-- for the precise wording). Also fixes Пылающая Луна's book_page, found
-- while reading through for this: printed page 299, confirmed from the
-- page marker right before its heading.

update moon_catalog set book_page = 299 where name = 'Пылающая Луна';

update moon_catalog set description = case name
  when 'Воющая Луна' then
    'Усиливает звук (доп. урон звуком от атак со звуковым уроном, слышимость x2). Звери воют: либо сбивают с ног и наносят звуковой урон, либо лечатся временными хитами. В пути — риск нападения зверей. Безумие сильнее обычного (+10 к броску по таблице безумия): кратковременное даёт звериные инстинкты (преим. на Ловкость, помеха на дальние атаки); долговременное/бессрочное — необратимая трансформация в Порождение бедствия или зверя (лечится только высшим восстановлением/исполнением желаний).'
  when 'Расколотая Луна' then
    'Существа: преим. на Скрытность, помеха на Восприятие; гуманоиды — преим. на спасброски от безумия. В пути — "лунный дождь" (рассеивает заклинания ≤5 ур.) и, при Гейстнахте, враждебная нежить. Безумие: луна питается жизнью персонажа (некротический урон каждый ход), на долгий срок — ломает конечность (лечится только после захода луны), на бессрочный — риск поглощения телом с мощным уроном.'
  when 'Пылающая Луна' then
    'Монстры получают сопротивление/иммунитет к огню и доп. огненный урон в рукопашной; звери могут сбивать с ног при разбеге. В пути — огненные столбы и иллюзорные пожары. Безумие: кратковременное поджигает персонажа (урон каждый ход + доп. урон атаками); долговременное — зачаровывает открытым пламенем; бессрочное — сопротивление или уязвимость к огню на весь срок безумия.'
  when 'Пустая Луна' then
    'Слабые монстры слепнут, но получают слепое зрение 30 футов и преим. на слух/нюх; появляется способность телепорта-контратаки. Тьма гасит свет и тёмное зрение. Безумие: провал спасброска Мудрости сам по себе даёт кратковременное безумие; долговременное/бессрочное играют с невидимостью/истинным зрением вплоть до необратимой слепоты.'
  when 'Взирающая Луна' then
    'Видна только существам с Инт 16+ и выше 4 уровня/ПО. На видящих её (кроме аберраций/монстров) действует порча, помеха на спасброски от смерти, скорость вдвое. В пути — риск потерять сознание от отчаяния. Безумие: кратковременное — роняет оружие и делает недееспособным; долговременное — помеха на спасброски Мудрости; бессрочное — невосприимчивость к луне или кома до её захода.'
  when 'Ледяная Луна' then
    'Монстры получают сопротивление/иммунитет к холоду и временные хиты при восходе. Видимость и пассивное Восприятие сильно падают, движение в быстром темпе = ослеплён. В пути — риск бурана с уроном холодом и шансом заблудиться. Любое безумие здесь может дать степень истощения. Долговременное/бессрочное — раздевание на морозе, обморожение (помеха на Ловкость, калечащий эффект до излечения безумия).'
  when 'Дремлющая Луна' then
    'Пристальный взгляд на луну = шанс телепортации (как переносящая дверь) или кратковременное безумие со случайным переносом. Кто её видел — при попытке покинуть Луярну просыпается обратно в городе без воспоминаний о попытке уйти (снимается только исполнением желаний). Безумие: кратковременное/долговременное — забывает навыки/владения или слабеет в Магии/Истории/Религии; бессрочное — не помнит ничего, что происходило под действием безумия.'
  when 'Желтая Корона' then
    'Усиливает урон и радиус излучения; произведения искусства под этой луной дают преим. на след. спасбросок от безумия, но гуманоиды помеха на спасброски от смерти. Постоянный яркий свет (−10 к Скрытности в пути). Безумие даёт случайную (правдивую или ложную) информацию о мире. Кратковременное/долговременное завязаны на тягу к свету/светобоязнь; бессрочное — крылья света или неконтролируемое свечение.'
  when 'Крадущийся Смольный Свет' then
    'Монстры (кроме гуманоидов) покрыты смолой — взрываются при первом огненном/излучающем уроне; тени липкие (движение вдвое медленнее, но преим. на инициативу в тьме); проклятия удваивают длительность. В пути — риск увязнуть в смоляной тьме (удушение/поглощение за несколько ходов). Безумие даёт штраф к КД/Ловкости и блокирует реакции. Кратковременное — выдаёт позицию смехом; долговременное — не может говорить/колдовать без спасброска; бессрочное — смоляная броня (+1 КД) или окаменение.'
  when 'Свет Кракена' then
    'Аберрации/гуманоиды выскальзывают из пут и воды; существа с хорошей скоростью плавания получают полёт; аберрации — гипнотизирующую приманку. Ливень, вдвое медленнее передвижение, риск быть утащенным щупальцем в небесный океан (урон при падении). Безумие: кратковременное — падение ничком и скорость 0; долговременное — риск помехи на атаки/спасброски в бою; бессрочное — свобода перемещения с уязвимостью к электричеству, либо превращение в водное существо (дышит только под водой).'
  when 'Кровавое Затмение' then
    'Долгое пребывание под лунным светом = риск кратковременного безумия; звери получают преим. против испуганных; вид потери сознания союзником грозит проклятием "неминуемой гибели" (авто-провалы спасбросков смерти). Любое безумие здесь может вызвать бешенство против союзников. Кратковременное отращивает когти; долговременное — клыки и временные хиты от урона (чувствительность к солнцу); бессрочное — вампиризм: тип становится Нежить, нужна кровь гуманоида иначе истощение.'
  when 'Кровавая Луна Перерождения' then
    'Восходит 3 дня, пока восходит — другие луны не могут взойти. На пике 50% шанс воскресить всех, кто умер за последние 30 дней (как истинное воскрешение), с проверкой на сохранение рассудка (сложнее с каждой предыдущей смертью). Воскрешённые, сохранившие рассудок, получают на тело Жертвенное клеймо (потусторонний орнамент).'
  else description
end
where name in (
  'Воющая Луна','Расколотая Луна','Пылающая Луна','Пустая Луна','Взирающая Луна','Ледяная Луна',
  'Дремлющая Луна','Желтая Корона','Крадущийся Смольный Свет','Свет Кракена','Кровавое Затмение',
  'Кровавая Луна Перерождения'
);
